// app/actions.js
'use server';
import { revalidateTag } from 'next/cache';

export async function updatePost(id) {
  // ... update post in DB
  revalidateTag('posts'); // any fetch tagged with 'posts' will be revalidated
}

// next.config.js
module.exports = {
  async headers() {
    return [
      {
        source: '/images/:path*',
        headers: [
          {
            key: 'Cache-Control',
            value: 'public, max-age=31536000, immutable',
          },
        ],
      },
    ];
  },
};
